const fs = require('fs');
const result = $input.first().json.stdout;
if (!result) return [];

const lines = result.split('\n').filter(l => l.trim() !== '').sort();
const EXT = /\.(jpg|jpeg|png|webp|gif)$/i;

const priceMap = {
  'CAKE': 2500,
  'CAKE 2 PISOS': 5500,
  'CAKE BANDEJA': 3500,
  'CAKE SENCILLO': 1800,
  'CAKE.CHOCOLATE': 2800,
  'CAPUCHINO': 150,
  'MAICENA': 200,
  'MINICAKE': 650
};

const categoryCounters = {};
const out = [];

function getBaseName(folder) {
  const f = folder.toUpperCase();
  if (f === 'CAKE' || f === 'CAKE SENCILLO') return 'Cake Simple';
  if (f.includes('CAKE')) {
    let rest = folder.replace(/cake/gi, '').trim();
    if (rest.startsWith('.') || rest.startsWith('-')) rest = rest.substring(1).trim();
    rest = rest.charAt(0).toUpperCase() + rest.slice(1);
    return `Cake de ${rest}`;
  }
  return folder;
}

for (const fullPath of lines) {
  if (!EXT.test(fullPath)) continue;

  const parts = fullPath.split('/');
  const fileName = parts.pop();
  const categoryFolder = parts.pop();
  const categoryKey = categoryFolder.toUpperCase();

  if (!categoryCounters[categoryKey]) categoryCounters[categoryKey] = 1;
  else categoryCounters[categoryKey]++;

  const baseName = getBaseName(categoryFolder);
  const displayName = `${baseName} Decoración #${categoryCounters[categoryKey]}`;

  const targetPath = `/data/yourdulceria/productosProcesados/${categoryFolder}/${displayName}.png`;
  if (fs.existsSync(targetPath)) {
    continue;
  }

  const priceCup = priceMap[categoryKey] || 500;

  out.push({
    json: {
      path: fullPath,
      fileName,
      category: categoryFolder,
      baseName,
      displayName,
      cupFormatted: priceCup.toLocaleString() + ' CUP'
    }
  });
}
return out;

const fs = require('fs');
const item = $input.first().json;

const logoPath = '/data/yourdulceria/logoYourDulceria.jpeg';
const productoPath = item.path;
const targetDir = `/data/yourdulceria/productosProcesados/${item.category}`;

try {
  if (!fs.existsSync(targetDir)) {
    fs.mkdirSync(targetDir, { recursive: true });
  }

  const logoBuffer = fs.readFileSync(logoPath);
  const productoBuffer = fs.readFileSync(productoPath);

  return [{
    json: {
      ...item,
      logoBase64: logoBuffer.toString('base64'),
      productoBase64: productoBuffer.toString('base64')
    }
  }];
} catch (e) {
  throw new Error(`Error en PrepareBase64: ${e.message}`);
}

